import pandas as pd
import numpy as np

# Load the data into a pandas DataFrame
data = pd.read_csv('chunks_csv/getisord/getisord_2021_no2.csv')

# Load the adjacency data into a pandas DataFrame
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Merge the data with the adjacency data to create a list of neighbors for each borough
data['neighbors'] = data['borough'].map(adjacency_data.set_index('borough')['neighbor'])

# Function to get the neighbors of a borough
def get_neighbors(borough):
    return adjacency_data[adjacency_data['borough'] == borough]['neighbor'].tolist()

# Function to get the total NO2 value for a borough and its neighbors
def get_total_no2(borough):
    neighbors = get_neighbors(borough)
    return data[data['borough'].isin([borough] + neighbors)]['NO2_value'].sum()

# Function to get the citywide average NO2 value
def get_citywide_average():
    return data['NO2_value'].mean()

# Function to calculate the Gi* statistic for a borough and its neighbors
def get_gi(borough):
    total_no2 = get_total_no2(borough)
    citywide_average = get_citywide_average()
    return (total_no2 - citywide_average) / (citywide_average * np.sqrt(len(get_neighbors(borough))))

# Function to identify the boroughs with a statistically significant Gi* value
def get_significant_boroughs(confidence_level):
    significant_boroughs = []
    for index, row in data.iterrows():
        if not np.isnan(row['NO2_value']):
            gi = get_gi(row['borough'])
            if abs(gi) > 1.96 if confidence_level == '95%' else abs(gi) > 2.576:
                significant_boroughs.append((row['borough'], gi, gi))
    return significant_boroughs

# Identify the boroughs with a statistically significant Gi* value
significant_boroughs = get_significant_boroughs('95%')

# Print the list of boroughs with significant Gi* values
print(f"FINAL ANSWER: {', '.join([f'{borough} (HOT, Gi*={gi}, gi_value={gi})' for borough, gi, _ in significant_boroughs])}")

# Print the number of data points used in the analysis
print(f"data_points_used = {len(data) - data['NO2_value'].isnull().sum()}")

# Print the list of boroughs with significant Gi* values for 99% confidence
significant_boroughs_99 = get_significant_boroughs('99%')
if significant_boroughs_99:
    print(f"FINAL ANSWER: {', '.join([f'{borough} (HOT, Gi*={gi}, gi_value={gi})' for borough, gi, _ in significant_boroughs_99])}")
else:
    print(f"FINAL ANSWER: none")
